// Test harness code: unwraps are the idiomatic assertion helpers here.
#![allow(clippy::unwrap_used, clippy::expect_used)]

//! Golden equivalence tests: Rust domain functions must reproduce the values
//! generated by the Python implementation (`tools/export_domain_golden.py`).

use forza_domain::car_names::car_match_key;
use forza_domain::lap::{
    RawGridEntry, detect_race_class, extract_class_letter, fahrenheit_to_celsius_str,
    format_lap_time_ms, is_dirty_lap, normalize_weather, parse_lap_time_ms, sanitize_driver_name,
    strip_dirty_symbol,
};
use forza_domain::normalizer::{fix_car_name, fix_track_name};
use forza_domain::ordering::{ordered_lap_key, track_order_map};
use forza_domain::reference_data::embedded_reference_data;
use forza_domain::review_rules::{
    ambiguous_raw_track, driver_name_review_trigger, has_numeric_name_prefix,
    has_suspicious_name_symbol, track_suggestions,
};

const FIXTURE: &str = include_str!("../../../fixtures/expected/domain_golden.json");

fn golden() -> serde_json::Value {
    serde_json::from_str(FIXTURE).expect("golden fixture parses")
}

fn optional_str(v: &serde_json::Value) -> Option<&str> {
    match v {
        serde_json::Value::Null => None,
        serde_json::Value::String(s) if s == "__NONE__" => None,
        serde_json::Value::String(s) => Some(s),
        other => panic!("unexpected value {other}"),
    }
}

fn number_or_string_i64(v: &serde_json::Value) -> Option<i64> {
    match v {
        serde_json::Value::Null => None,
        serde_json::Value::Number(n) => n.as_i64(),
        serde_json::Value::String(s) => s.parse::<i64>().ok(),
        other => panic!("unexpected value {other}"),
    }
}

fn f64_or_string(v: &serde_json::Value) -> Option<f64> {
    match v {
        serde_json::Value::Null => None,
        serde_json::Value::Number(n) => n.as_f64(),
        serde_json::Value::String(s) => s.parse::<f64>().ok(),
        other => panic!("unexpected value {other}"),
    }
}

#[test]
fn parse_lap_time_ms_matches_python() {
    for pair in golden()["parse_lap_time_ms"].as_array().unwrap() {
        let input = pair[0].as_str().unwrap();
        let expected = number_or_string_i64(&pair[1]);
        let got = parse_lap_time_ms(optional_str(&pair[0]));
        assert_eq!(got, expected, "parse_lap_time_ms({input:?})");
    }
}

#[test]
fn format_lap_time_ms_matches_python() {
    let section = &golden()["format_lap_time_ms"];
    for (args, expected) in section["values"]
        .as_array()
        .unwrap()
        .iter()
        .zip(section["results"].as_array().unwrap().iter())
    {
        let ms = args[0].as_i64().unwrap();
        let dirty = args[1].as_bool().unwrap();
        let got = format_lap_time_ms(ms, dirty).unwrap();
        assert_eq!(got, expected.as_str().unwrap(), "format({ms}, {dirty})");
    }
}

