#[test]
fn fahrenheit_to_celsius_matches_python() {
    for row in golden()["fahrenheit_to_celsius"].as_array().unwrap() {
        let input = optional_str(&row[0]);
        let lo = row[1].as_f64().unwrap();
        let hi = row[2].as_f64().unwrap();
        let expected = f64_or_string(&row[3]);
        let got = fahrenheit_to_celsius_str(input, lo, hi);
        match (got, expected) {
            (None, None) => {}
            (Some(g), Some(e)) => assert!((g - e).abs() < 1e-9, "{g} != {e}"),
            other => panic!("mismatch {other:?}"),
        }
    }
}

