#[test]
fn ambiguous_and_suggestions_match_python() {
    for pair in golden()["ambiguous_raw_track"].as_array().unwrap() {
        assert_eq!(
            ambiguous_raw_track(Some(pair[0].as_str().unwrap())),
            pair[1].as_str().unwrap()
        );
    }
    let refs = embedded_reference_data();
    for pair in golden()["track_suggestions"].as_array().unwrap() {
        assert_eq!(
            track_suggestions(pair[0].as_str().unwrap(), &refs.tracks),
            pair[1]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_str().unwrap().to_string())
                .collect::<Vec<_>>(),
            "suggestions({:?})",
            pair[0]
        );
    }
}

struct GoldenRow<'a> {
    row: &'a serde_json::Value,
}

impl<'a> forza_domain::ordering::LapRowLike for GoldenRow<'a> {
    fn track(&self) -> &str {
        self.row["track"].as_str().unwrap()
    }
    fn race_class(&self) -> &str {
        self.row["race_class"].as_str().unwrap()
    }
    fn weather(&self) -> Option<&str> {
        self.row["weather"].as_str()
    }
    fn best_lap_ms(&self) -> i64 {
        self.row["best_lap_ms"].as_i64().unwrap()
    }
    fn driver(&self) -> &str {
        self.row["driver"].as_str().unwrap()
    }
    fn car(&self) -> &str {
        self.row["car"].as_str().unwrap()
    }
}

#[test]
fn ordering_keys_match_python() {
    let section = &golden()["ordering_keys"];
    let order_list: Vec<String> = section["order_map_input"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let map = track_order_map(&order_list);
    for (row, expected) in section["rows"]
        .as_array()
        .unwrap()
        .iter()
        .zip(section["keys"].as_array().unwrap().iter())
    {
        let key = ordered_lap_key(&GoldenRow { row }, &map);
        let exp = &expected[0];
        assert_eq!(key.0 as u64, exp[0].as_u64().unwrap());
        assert_eq!(key.1, exp[1].as_str().unwrap());
        assert_eq!(key.2 as u64, exp[2].as_u64().unwrap());
        assert_eq!(key.3, exp[3].as_str().unwrap());
        assert_eq!(key.4, exp[4].as_str().unwrap_or(""));
        assert_eq!(key.5, exp[5].as_i64().unwrap());
        assert_eq!(key.6, exp[6].as_str().unwrap());
        assert_eq!(key.7, exp[7].as_str().unwrap());
    }
}
